export interface CartItem {
  id: number;
  name: string;
  price: number;
  quantity: number;
}

export type CartAction =
  | { type: 'add'; item: { id: number; name: string; price: number } }
  | { type: 'remove'; id: number }
  | { type: 'updateQuantity'; id: number; quantity: number }
  | { type: 'clear' };

import { CartItem, CartAction } from './types';

export function cartReducer(state: CartItem[], action: CartAction): CartItem[] {
  switch (action.type) {
    case 'add': {
      const existing = state.find(item => item.id === action.item.id);
      if (existing) {
        return state.map(item =>
          item.id === action.item.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...state, { ...action.item, quantity: 1 }];
    }
    case 'remove':
      return state.filter(item => item.id !== action.id);
    case 'updateQuantity':
      return state.map(item =>
        item.id === action.id
          ? { ...item, quantity: action.quantity }
          : item
      );
    case 'clear':
      return [];
    default:
      return state;
  }
}

import { CartItem } from './types';

export function getCartTotal(items: CartItem[]): number {
  return items.reduce((sum, item) => sum + item.price * item.quantity, 0);
}

export function getItemCount(items: CartItem[]): number {
  return items.reduce((sum, item) => sum + item.quantity, 0);
}

import { CartItem } from './types';

interface CartDisplayProps {
  items: CartItem[];
  onRemove: (id: number) => void;
}

export function CartDisplay({ items, onRemove }: CartDisplayProps) {
  return (
    <ul>
      {items.map(item => (
        <li key={item.id}>
          {item.name} x{item.quantity}
          <button onClick={() => onRemove(item.id)}>Remove</button>
        </li>
      ))}
    </ul>
  );
}

import { useReducer } from 'react';
import { cartReducer } from './cartReducer';
import { getCartTotal, getItemCount } from './cartUtils';
import { CartDisplay } from './CartDisplay';

export function App() {
  const [items, dispatch] = useReducer(cartReducer, []);

  return (
    <div>
      <p>Items: {getItemCount(items)}</p>
      <p>Total: ${getCartTotal(items).toFixed(2)}</p>
      <button onClick={() => dispatch({ type: 'add', item: { id: 1, name: 'Widget', price: 9.99 } })}>
        Add Widget
      </button>
      <button onClick={() => dispatch({ type: 'clear' })}>Clear</button>
      <CartDisplay items={items} onRemove={(id) => dispatch({ type: 'remove', id })} />
    </div>
  );
}
